.intel_syntax noprefix
.global _main

.data
	.LCharacter: .ascii "a"
	.Ltmp64: .byte 0, 0, 0, 0, 0, 0, 0, 0
	.LsigStruct:
		.Lsa_handler: .quad 0
		.Lsa_handler_2: .quad 0
		.quad 0, 0



.text
	

.Ltext0:
killParent:
    mov rax, 0x2000027
    syscall

    mov rdi, rax
    mov rsi, 9
    mov rax, 0x2000025
    syscall

    mov rdi, 0
    mov rax, 60
    syscall
    ret

_main:
push rax
    push rdi
    push rsi
    push rdx
    push r10
    push rcx
    push r11
    
    lea rax, [rip + killParent]
    mov [rip + .Lsa_handler], rax
    mov [rip + .Lsa_handler_2], rax

    mov rax, 0x200002E
    mov rdi, 2
    lea rsi, [rip + .LsigStruct]
    xor rdx, rdx
    mov r10, 8
    syscall
    
    pop r11
    pop rcx
    pop r10
    pop rdx
    pop rsi
    pop rdi
    pop rax

	mov BYTE PTR [rip + .LCharacter], 'H'
